import inspect
from fastapi.dependencies.models import Dependant

class AsyncCallClass:
    async def __call__(self):
        return "hello"

class GenCallClass:
    def __call__(self):
        yield "hello"

class AsyncGenCallClass:
    async def __call__(self):
        yield "hello"

def test_is_coroutine_callable():
    dep = Dependant(call=AsyncCallClass)
    assert dep.is_coroutine_callable is False, "AsyncCallClass should not be treated as coroutine callable"

def test_is_gen_callable():
    dep = Dependant(call=GenCallClass)
    assert dep.is_gen_callable is False, "GenCallClass should not be treated as gen callable"

def test_is_async_gen_callable():
    dep = Dependant(call=AsyncGenCallClass)
    assert dep.is_async_gen_callable is False, "AsyncGenCallClass should not be treated as async gen callable"

if __name__ == "__main__":
    try:
        test_is_coroutine_callable()
        test_is_gen_callable()
        test_is_async_gen_callable()
        print("All tests passed!")
    except AssertionError as e:
        print(f"Assertion failed: {e}")
        exit(1)
